import{_ as e,o as d,c as o,ak as a}from"./chunks/framework.DxrHb2fb.js";const p=JSON.parse('{"title":"组件家族与模式","description":"","frontmatter":{},"headers":[],"relativePath":"design/patterns.md","filePath":"design/patterns.md","lastUpdated":1790029076000}'),r={name:"design/patterns.md"};function i(n,t,l,c,s,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="组件家族与模式" tabindex="-1">组件家族与模式 <a class="header-anchor" href="#组件家族与模式" aria-label="Permalink to &quot;组件家族与模式&quot;">​</a></h1><p>新组件先归族，再决定局部样式。家族给出尺寸、状态、焦点、禁用与按压的配方（<code>family/*.css</code>），组件只映射自己的覆盖槽；门禁按家族逐成员比对，同族成员的同类部件逐条同值。</p><h2 id="六个家族" tabindex="-1">六个家族 <a class="header-anchor" href="#六个家族" aria-label="Permalink to &quot;六个家族&quot;">​</a></h2><table tabindex="0"><thead><tr><th>家族</th><th>典型组件</th><th>配方给什么</th></tr></thead><tbody><tr><td>Action Control</td><td>Button、Toggle、ToggleGroup item、分页按钮、图标按钮、Toolbar item、Segmented item、各类 trigger</td><td>高度、内边距、图标随档、缺省语气（只有 Button 品牌实心）、按承载面的交互阶梯、120 / 200ms 按压、焦点、禁用、加载。六个 profile：<code>text</code>、<code>icon</code>、<code>field-inset</code>（字段内的清空 / 展开小钮）、<code>floating</code>（悬浮单图标动作，圆形）、<code>row</code> 与 <code>disclosure-trigger</code>（铺满一行、只换面）</td></tr><tr><td>Field Chrome</td><td>Input、Textarea、Select trigger、Date / Time field、Combobox、Cascader、TagsInput、PinInput、PromptInput</td><td>静息描边式外壳（不填底）、<code>outline / subtle / ghost</code> 三档 × rest / hover / focus / invalid / disabled / readOnly / loading 七态、占位、前后缀、清空、标签与说明排版、缺省宽</td></tr><tr><td>Collection Item</td><td>Menu item、Listbox item、Tree node、Table row、Transfer item、SideNav link、Tabs line trigger、Anchor / Breadcrumb link、NavigationMenu / Menubar trigger</td><td>highlighted、按集合语境（<code>overlay / page / nav</code>）的 selected / current 标记、pressed 只换面、disabled、缩进、指示器</td></tr><tr><td>Surface</td><td>Card、Alert、Panel、CodeView、DiffView、Log、JsonViewer、ToolCall、Reasoning、Approval、QuestionFlow、Accordion / Toolbar / PageHeader 的 outline 档、各类容器面</td><td>边界三选一、raised 逐部件登记、标题与说明排版、内衬只走 <code>--xh-surface-*</code>、层级</td></tr><tr><td>Overlay</td><td>Popover、Menu、Select content、Dialog、Drawer、Tooltip、NavigationMenu content、日期 / 时间面板</td><td>Portal、定位、遮罩、材质按内容判定、进退场按锚定关系、浮层滚动面、焦点归还</td></tr><tr><td>Feedback</td><td>Toast、Notification、Progress、Skeleton</td><td>状态语气、sheet 面描边、计时、暂停、消除、加载与即时反馈</td></tr></tbody></table><p>一个组件可以组合多个家族，但每个部件只有一个主要身份。归族的判据是功能：用户直接触发动作 → Action Control；输入或选择值 → Field Chrome；在集合中导航、选择或操作条目 → Collection Item；长期承载一组内容 → Surface；脱离文档流临时覆盖页面 → Overlay；表达任务过程或结果 → Feedback。</p><h2 id="视觉轴" tabindex="-1">视觉轴 <a class="header-anchor" href="#视觉轴" aria-label="Permalink to &quot;视觉轴&quot;">​</a></h2><p>组件只允许这几条公共轴，不允许私有轴：</p><table tabindex="0"><thead><tr><th>轴</th><th>取值</th><th>说明</th></tr></thead><tbody><tr><td><code>size</code></td><td><code>sm / md / lg</code></td><td>md 缺省；换高度、内衬、间隙、字号与图标，不随断点改</td></tr><tr><td><code>variant</code></td><td><code>outline / subtle / ghost</code>，可按下的表面多一档 <code>solid</code></td><td>结构形态，不表达业务状态；缺省等价 outline，Tabs 缺省 <code>line</code></td></tr><tr><td><code>tone</code></td><td><code>brand / neutral / danger / warning / success / info</code></td><td>语气；缺省中性，只有 Button 缺省品牌</td></tr><tr><td><code>data-density</code></td><td><code>comfortable / compact</code></td><td>环境轴，由控制器投影，组件不各自定义</td></tr></tbody></table><p><code>bordered</code>、<code>borderless</code>、<code>plain | surface</code>、<code>primary | secondary</code> 这类私有轴一律不存在：有框无框走 <code>variant</code>，主次走 <code>variant</code> + <code>tone</code>。</p><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>每个组件按实际能力补齐 rest、hover、pressed、focus-visible、selected / open、disabled、loading、invalid 与退出状态，由 Headless 投影成 <code>data-*</code> 状态事实，皮肤只映射：</p><ul><li>hover、active、selected 从当前语义面派生，不切换到无关颜色。</li><li>disabled 同时调整前景或背景并关闭交互，不只降 opacity。</li><li>错误、选择、加载与警告不能只靠颜色。</li><li>暗色下 overlay 必须能从 canvas 与 surface 中辨认。</li></ul><h2 id="七个分类怎么选" tabindex="-1">七个分类怎么选 <a class="header-anchor" href="#七个分类怎么选" aria-label="Permalink to &quot;七个分类怎么选&quot;">​</a></h2><p>组件总览按用途分七类，与家族是两个维度——分类回答&quot;我要做什么&quot;，家族回答&quot;它长什么样&quot;：</p><table tabindex="0"><thead><tr><th>分类</th><th>选型要点</th></tr></thead><tbody><tr><td><a href="/components/#通用">通用</a></td><td>Button 只给动作，导航用链接；Toggle 表达开关态而不是触发动作；Clipboard、DownloadTrigger 是带结果反馈的动作钮</td></tr><tr><td><a href="/components/#布局">布局</a></td><td>页面骨架用 Layout，局部排列用 Flex / Grid，可拖动分栏用 Splitter；见 <a href="/design/layout">布局</a></td></tr><tr><td><a href="/components/#导航">导航</a></td><td>页级切换用 Tabs，站内层级用 SideNav / NavigationMenu / Menubar，位置用 Breadcrumb / Anchor / Steps，右键与更多用 ContextMenu / Menu</td></tr><tr><td><a href="/components/#数据录入">数据录入</a></td><td>少于七个互斥项用 RadioGroup，更多用 Select；可输入的候选用 Combobox；多选用 CheckboxGroup 或 TagsInput；日期优先分段输入（DateField）再加日历（DatePicker）；整表用 Form + Field 承担校验与重置</td></tr><tr><td><a href="/components/#数据展示">数据展示</a></td><td>记录用 Table，层级用 Tree，键值对用 Descriptions，长列表用 Virtualizer / InfiniteScroll，状态用 Tag / Badge</td></tr><tr><td><a href="/components/#反馈">反馈</a></td><td>页内静态提示用 Alert，操作结果用 Toast（短、自动消失）或 Notification（可停留、可动作），进行中用 Progress / Spinner / Skeleton / LoadingBar</td></tr><tr><td><a href="/components/#浮层">浮层</a></td><td>轻量补充用 Tooltip / HoverCard / Popover，需要确认用 Popconfirm，需要打断用 Dialog，侧边任务流用 Drawer，命令入口用 Command</td></tr><tr><td><a href="/components/#ai-对话">AI 对话</a></td><td>输入用 PromptInput，流式正文用 MarkdownStream / MessageFeed，工具与推理用 ToolCall / Reasoning，审批与提问用 Approval / QuestionFlow</td></tr></tbody></table><h2 id="示例与总览" tabindex="-1">示例与总览 <a class="header-anchor" href="#示例与总览" aria-label="Permalink to &quot;示例与总览&quot;">​</a></h2><ul><li>第一个示例用最少结构展示核心用途；一个示例只证明一个意图；不为覆盖 API 保留重复示例；示例不写内联宽度。</li><li>组件总览用独立极简预览：一律 md 缺省档、缺省 variant，tone 只在语气即核心用途时允许一个非 neutral 值；浮层类展示已打开的静态面板。</li><li>复杂业务组合放到 <a href="/examples/">示例</a> 一册，不塞进基础组件专页。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/design/principles">设计原则</a> · <a href="/design/shape">形状与边界</a> · <a href="/design/motion">动效</a></li><li>指南：<a href="/guide/anatomy">解剖与部件契约</a> · <a href="/guide/connect">connect 与属性产出</a></li></ul>',19)])])}const b=e(r,[["render",i]]);export{p as __pageData,b as default};
